def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit("ashira_510: no hunk on " + rel)
    for old, new in HUNKS[rel]:
        n = txt.count(old)
        if n != 1:
            raise SystemExit(f"ashira_510: anchor x{n} in the live {rel}: {old.strip()[:70]!r}")
        txt = txt.replace(old, new)
    return txt
